package com.paytrace.investigation; import com.paytrace.decision.*; import com.paytrace.explanation.*; import com.paytrace.incident.*; import com.paytrace.integrity.*; import com.paytrace.payment.*; import com.paytrace.recovery.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class InvestigationService { private final PaymentService payments;private final PaymentEventRepository events;private final IntegrityEngine integrity;private final IncidentDetector incidents;private final DecisionIntelligencePort decisions;private final RecoveryPolicy recovery;private final ExplanationModelPort explanations; public InvestigationService(PaymentService p,PaymentEventRepository e,IntegrityEngine in,IncidentDetector id,DecisionIntelligencePort d,RecoveryPolicy r,ExplanationModelPort x){payments=p;events=e;integrity=in;incidents=id;decisions=d;recovery=r;explanations=x;} public InvestigationView investigate(UUID id){var payment=payments.reconstruct(id);var found=incidents.investigate(id);var decision=decisions.assess(payment,found);var recommendation=recovery.decide(payment,found,decision);return new InvestigationView(payment,events.findByPaymentIdOrderByOccurredAtAsc(id),integrity.results(id),found,decision,recommendation,explanations.explain(payment,found,decision,recommendation));} }
